import React, { useContext, useState } from 'react';

import { ColumnSettingsButton } from './ColumnSettingsButton.js';
import { ColumnSettingsModal } from './ColumnSettingsModal.js';
import { uuidv4 } from '../../../core/utils/uuidv4.js';
import { Flex } from '../../../layouts-core/flex/Flex.js';
import { DataTableContext } from '../../contexts/DataTableContext.js';

// #region Typings
type ColumnSettingsProps = {
  visibilitySettings: boolean;
  columnOrderSettings: boolean;
};
// #endregion Typings

/**
 * DataTable column settings. Internally used component that contains trigger button and an modal. The modal
 * contains the list of all columns and if visibilitySettings provided 1) a filter 2) a show/hide all checkbox, and 3) individual checkboxes for
 * each column. If columnOrdderSettings is provided list will contain also up and down arrows buttons responsible for the column ordering.
 * @internal
 * @returns ColumnSettings element
 */
export const _ColumnSettings = (props: ColumnSettingsProps) => {
  const { visibilitySettings, columnOrderSettings } = props;
  const {
    allOrderingColumns,
    columnVisibility,
    onVisibilityChange,
    onColumnOrderChange,
  } = useContext(DataTableContext);

  const [modalKey, setModalKey] = useState<string | null>(null);
  const isInitialRender = modalKey === null;

  // Every time the user clicks the trigger button we set the new key
  // to the ColumnSettingsModal component so that react recreates the modal component and resets its local state.
  // By doing that, we update the local state of the modal (visibility and allColumns) to syncronise it with the state
  // changes that come from outside like for example from column actions.
  const toggleColumnSettingsModal = () => {
    setModalKey(uuidv4());
  };

  if (!columnOrderSettings && !visibilitySettings) {
    return null;
  }

  return (
    <Flex>
      <ColumnSettingsButton onClick={toggleColumnSettingsModal} />
      {!isInitialRender && (
        <ColumnSettingsModal
          key={modalKey}
          allColumns={allOrderingColumns ?? []}
          visibility={columnVisibility}
          visibilitySettings={visibilitySettings}
          columnOrderSettings={columnOrderSettings}
          onVisibilityChange={onVisibilityChange}
          onColumnOrderChange={onColumnOrderChange}
        />
      )}
    </Flex>
  );
};
